// =====================================================================
// IUH Fast Login — Ultra-Accurate Single Glyph CNN Solver (< 400 KB)
// 100% Offline pure JavaScript inference with zero dependencies
// =====================================================================
(() => {
  "use strict";

  const CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const WEIGHTS_B64 = "";

  let _weights = null;

  function initWeights() {
    if (_weights) return _weights;
    const binStr = atob(WEIGHTS_B64);
    const len = binStr.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binStr.charCodeAt(i);
    }
    const floats = new Float32Array(bytes.buffer);
    let offset = 0;
    function slice(size) {
      const s = floats.subarray(offset, offset + size);
      offset += size;
      return s;
    }

    _weights = {
      w1: slice(16 * 1 * 3 * 3),
      b1: slice(16),
      w2: slice(32 * 16 * 3 * 3),
      b2: slice(32),
      w_fc1: slice(64 * 32 * 7 * 6),
      b_fc1: slice(64),
      w_fc2: slice(36 * 64),
      b_fc2: slice(36)
    };
    return _weights;
  }

  function convReluPool(x, cIn, h, wIn, cOut, w, b) {
    const outH = h >> 1;
    const outW = wIn >> 1;
    const out = new Float32Array(cOut * outH * outW);
    const convOut = new Float32Array(h * wIn);

    for (let oc = 0; oc < cOut; oc++) {
      convOut.fill(b[oc]);
      const wBaseOc = oc * cIn * 9;

      for (let ic = 0; ic < cIn; ic++) {
        const xBase = ic * h * wIn;
        const wBase = wBaseOc + ic * 9;

        for (let di = 0; di < 3; di++) {
          for (let dj = 0; dj < 3; dj++) {
            const weight = w[wBase + di * 3 + dj];
            if (weight === 0) continue;

            const iStart = Math.max(0, 1 - di);
            const iEnd = Math.min(h, h + 1 - di);
            const jStart = Math.max(0, 1 - dj);
            const jEnd = Math.min(wIn, wIn + 1 - dj);

            for (let i = iStart; i < iEnd; i++) {
              const srcI = i + di - 1;
              const dstRow = i * wIn;
              const srcRow = xBase + srcI * wIn;

              for (let j = jStart; j < jEnd; j++) {
                const srcJ = j + dj - 1;
                convOut[dstRow + j] += x[srcRow + srcJ] * weight;
              }
            }
          }
        }
      }

      // ReLU + MaxPool 2x2
      const outBase = oc * outH * outW;
      for (let oi = 0; oi < outH; oi++) {
        const i0 = oi * 2 * wIn;
        const i1 = (oi * 2 + 1) * wIn;
        const outRow = outBase + oi * outW;

        for (let oj = 0; oj < outW; oj++) {
          const j0 = oj * 2;
          const j1 = oj * 2 + 1;

          const v00 = convOut[i0 + j0];
          const v01 = convOut[i0 + j1];
          const v10 = convOut[i1 + j0];
          const v11 = convOut[i1 + j1];

          let maxVal = v00 > v01 ? v00 : v01;
          if (v10 > maxVal) maxVal = v10;
          if (v11 > maxVal) maxVal = v11;

          out[outRow + oj] = maxVal > 0 ? maxVal : 0;
        }
      }
    }
    return out;
  }

  // Phân loại 1 glyph 24x28 thành 1 ký tự (0-9, A-Z)
  function classifyGlyph(glyph24x28) {
    const weights = initWeights();
    // glyph: Float32Array(28 * 24), h=28, w=24, cIn=1
    // Layer 1: conv1 (16, 1, 3, 3) -> out (16, 14, 12)
    const l1 = convReluPool(glyph24x28, 1, 28, 24, 16, weights.w1, weights.b1);
    // Layer 2: conv2 (32, 16, 3, 3) -> out (32, 7, 6)
    const l2 = convReluPool(l1, 16, 14, 12, 32, weights.w2, weights.b2);

    // FC1: Linear(1344, 64) + ReLU
    const flatSize = 32 * 7 * 6; // 1344
    const fc1Out = new Float32Array(64);
    for (let k = 0; k < 64; k++) {
      let sum = weights.b_fc1[k];
      const wBase = k * flatSize;
      for (let i = 0; i < flatSize; i++) {
        sum += l2[i] * weights.w_fc1[wBase + i];
      }
      fc1Out[k] = sum > 0 ? sum : 0;
    }

    // FC2: Linear(64, 36) -> argmax
    let maxScore = -1e9;
    let bestChar = "0";
    for (let k = 0; k < 36; k++) {
      let sum = weights.b_fc2[k];
      const wBase = k * 64;
      for (let i = 0; i < 64; i++) {
        sum += fc1Out[i] * weights.w_fc2[wBase + i];
      }
      if (sum > maxScore) {
        maxScore = sum;
        bestChar = CHARS[k];
      }
    }
    return bestChar;
  }

  globalThis.IUH_GLYPH_SOLVER = {
    classify: classifyGlyph
  };
})();
